import { type Generated, type ColumnType, Kysely } from 'kysely'
import { PostgresJSDialect } from 'kysely-postgres-js'
import postgres from 'postgres'
import { getCloudflareContext } from '@opennextjs/cloudflare'

interface ProfileTable {
  // Columns that are generated by the database should be marked
  // using the `Generated` type. This way they are automatically
  // made optional in inserts and updates.
  id: Generated<number>
  name: string
  email: string
  image: string

  // You can specify a different type for each operation (select, insert and
  // update) using the `ColumnType<SelectType, InsertType, UpdateType>`
  // wrapper. Here we define a column `createdAt` that is selected as
  // a `Date`, can optionally be provided as a `string` in inserts and
  // can never be updated:
  createdAt: ColumnType<Date, string | undefined, never>
}

// Keys of this interface are table names.
export interface Database {
  profiles: ProfileTable
}

// The table lives in `public`, which Supabase's Data API (PostgREST) serves to
// anyone holding the project's anon key. It has row-level security ENABLED and
// no policy, so `anon` and `authenticated` read and write nothing through that
// API, while the app — which connects through Hyperdrive as the table's owner —
// is not subject to it. The table is created by the migrations (packages/db,
// applied by db-migrate before the Worker deploys; `pnpm db:migrate` locally),
// never by the page.

function connect(connectionString: string, options: postgres.Options<Record<string, never>>) {
  return new Kysely<Database>({
    dialect: new PostgresJSDialect({ postgres: postgres(connectionString, options) }),
  })
}

// One client per request. On the Worker the connection string is the
// HYPERDRIVE binding's (Cloudflare pools and caches the Supabase connection),
// and the Workers runtime refuses to reuse a socket across requests, so a
// module-level client — upstream's `postgres(POSTGRES_URL, { ssl: 'require' })`
// — would fail every request after the first. Each request's client is kept
// against that request's ExecutionContext, so every query of one request
// shares it and nothing outlives it. Without a Cloudflare context (`next dev`
// without wrangler, scripts) it is POSTGRES_URL, as the template had it.
const perRequest = new WeakMap<object, Kysely<Database>>()
let local: Kysely<Database> | undefined

function current(): Kysely<Database> {
  let cf: ReturnType<typeof getCloudflareContext> | undefined
  try {
    cf = getCloudflareContext()
  } catch {
    cf = undefined // no Cloudflare context
  }
  const connectionString = cf?.env.HYPERDRIVE?.connectionString
  if (cf && connectionString) {
    const request = cf.ctx as object // the request's ExecutionContext
    let client = perRequest.get(request)
    if (!client) {
      // `fetch_types` stays on (postgres.js's default). kysely-postgres-js runs
      // every query on a reserved connection (`sql.reserve()`), and postgres.js
      // 3.4 hands a freshly opened connection to a waiting reserve only from
      // its type-fetch step: with `fetch_types: false` the reserve never
      // resolves and the request hangs (spikes/postgres-kysely.md). The fetch
      // is one catalog read per connection, which Hyperdrive can cache.
      client = connect(connectionString, { max: 5, prepare: false })
      perRequest.set(request, client)
    }
    return client
  }
  return (local ??= connect(process.env.POSTGRES_URL!, { ssl: 'require' }))
}

// Upstream's `db`, unchanged at every call site: each property read resolves
// to the current request's client.
export const db: Kysely<Database> = new Proxy({} as Kysely<Database>, {
  get(_target, property) {
    const client = current()
    const value = Reflect.get(client, property, client)
    return typeof value === 'function' ? value.bind(client) : value
  },
})
export { sql } from 'kysely'
